(p, r) = (786433, 10)

def DFT(a, w, order):
	if len(a) == 1:
		return [a[0]] * order
	(feven, fodd, res, x, half_order) = (DFT(a[0::2], w * w % p, order // 2), DFT(a[1::2], w * w % p, order // 2), [0] * order, 1, order // 2)
	for i in range(order // 2):
		(res[i], res[i + half_order]) = ((feven[i] + x * fodd[i]) % p, (feven[i] - x * fodd[i]) % p)
		x = x * w % p
	return res

def calcPolynomialValues(a):
	(dft, res, x) = (DFT(a, r, p - 1), [a[0]] + [0] * (p - 1), 1)
	for i in range(p - 1):
		res[x] = dft[i]
		x = x * r % p
	return res
(n, pol_values) = (int(input()), calcPolynomialValues(list(map(int, input().split()))))
for i in range(int(input())):
	print(pol_values[int(input())])
